description:
PIDs are reused, handles are not (lesson 1.01). Model that difference: a tracker that hands out **tickets**, like handles, each referring to one particular run of a process even after its PID has been given to another.

```cpp
class Tracker
{
public:
    void started(std::uint32_t pid, const std::string& name);
    void exited(std::uint32_t pid, std::uint32_t code);
    int open(std::uint32_t pid);
    bool isRunning(int ticket) const;
    std::optional<std::string> nameOf(int ticket) const;
    std::optional<std::uint32_t> exitCodeOf(int ticket) const;
};
```

- **started** records that a process with this PID and name is now running. (The PID is never in use twice at the same time.)
- **exited** records that the **currently running** process with that PID ended with `code`. An unknown PID is ignored.
- **open** returns a new ticket (0, 1, 2, ...) for the process currently running with that PID, or -1 if none is.
- A ticket keeps referring to the same process: `nameOf` and `exitCodeOf` answer for it even after it exits and its PID is reused. `exitCodeOf` is `std::nullopt` while it runs; any unknown ticket gives `std::nullopt` and `isRunning` false.

starter.solution.cpp:
#include <cstdint>
#include <optional>
#include <string>

class Tracker
{
public:
    void started(std::uint32_t pid, const std::string& name) {}
    void exited(std::uint32_t pid, std::uint32_t code) {}
    int open(std::uint32_t pid) { return -1; }
    bool isRunning(int ticket) const { return false; }
    std::optional<std::string> nameOf(int ticket) const { return std::nullopt; }
    std::optional<std::uint32_t> exitCodeOf(int ticket) const { return std::nullopt; }
};

solution.solution.cpp:
#include <cstdint>
#include <map>
#include <optional>
#include <string>
#include <vector>

class Tracker
{
public:
    void started(std::uint32_t pid, const std::string& name)
    {
        runs.push_back({ name, std::nullopt });
        running[pid] = runs.size() - 1;
    }

    void exited(std::uint32_t pid, std::uint32_t code)
    {
        const auto it{ running.find(pid) };
        if (it == running.end()) return;
        runs[it->second].exitCode = code;
        running.erase(it);
    }

    int open(std::uint32_t pid)
    {
        const auto it{ running.find(pid) };
        if (it == running.end()) return -1;
        tickets.push_back(it->second);
        return static_cast<int>(tickets.size()) - 1;
    }

    bool isRunning(int ticket) const
    {
        const Run* r{ find(ticket) };
        return r && !r->exitCode;
    }

    std::optional<std::string> nameOf(int ticket) const
    {
        const Run* r{ find(ticket) };
        if (!r) return std::nullopt;
        return r->name;
    }

    std::optional<std::uint32_t> exitCodeOf(int ticket) const
    {
        const Run* r{ find(ticket) };
        return r ? r->exitCode : std::nullopt;
    }

private:
    struct Run { std::string name; std::optional<std::uint32_t> exitCode; };
    std::vector<Run> runs;
    std::map<std::uint32_t, std::size_t> running;
    std::vector<std::size_t> tickets;

    const Run* find(int ticket) const
    {
        if (ticket < 0 || ticket >= static_cast<int>(tickets.size())) return nullptr;
        return &runs[tickets[ticket]];
    }
};

unitTests:
TEST("tickets follow one process") {
    Tracker t;
    t.started(4120, "build.exe");
    const int ticket{ t.open(4120) };
    CHECK_EQ(ticket, 0);
    CHECK(t.isRunning(ticket));
    CHECK_EQ(t.nameOf(ticket).value_or("?"), std::string("build.exe"));
    CHECK(!t.exitCodeOf(ticket).has_value());
    t.exited(4120, 0);
    CHECK(!t.isRunning(ticket));
    CHECK_EQ(t.exitCodeOf(ticket).value_or(99), 0u);
}
TEST("PID reuse does not confuse a ticket") {
    Tracker t;
    t.started(880, "helper.exe");
    const int old{ t.open(880) };
    t.exited(880, 0xC0000005);
    t.started(880, "notepad.exe");
    const int fresh{ t.open(880) };
    CHECK(old != fresh);
    CHECK_EQ(t.nameOf(old).value_or("?"), std::string("helper.exe"));
    CHECK_EQ(t.exitCodeOf(old).value_or(0), 0xC0000005u);
    CHECK_EQ(t.nameOf(fresh).value_or("?"), std::string("notepad.exe"));
    CHECK(t.isRunning(fresh));
}
TEST("nothing to open") {
    Tracker t;
    CHECK_EQ(t.open(1234), -1);
    t.exited(1234, 1);
    t.started(5, "a.exe");
    t.exited(5, 3);
    CHECK_EQ(t.open(5), -1);
    CHECK(!t.nameOf(7).has_value());
    CHECK(!t.isRunning(-1));
}

